import './App.css';
import {useState } from 'react';
import './equationBoard.css';

function App() {

  const nums = [891, 94, 483, 492];

  const [seq, setSeq] = useState('891 , 94 , 483 , 492');

  function incident(algorithm) {
    let currentNum = nums[nums.length - 1].toString();
    let index;

    if (algorithm === "sum sequential") {
      index = nums.length - 1;
      currentNum = (currentNum + nums[index - 1]).toString();

      while (true) {
        if (currentNum < 10) {
          let [years, months, days, _] = getDate(currentNum);
          return [years, months, days];
        }
        if (currentNum >= 10000){
          return false;
        }
        currentNum = (currentNum + nums[index]).toString();
        index--;
      }
    } else if (algorithm === "subtract sequential") {
      if (nums.length > 1) {
        index = nums.length - 1;
        currentNum = (currentNum - nums[index]).toString();

        while (true) {
          if (currentNum < 0) {
            return "not possible, cannot go negative"
          }

          if (currentNum < 10) {
            let [years, months, days, _] = getDate(currentNum);
            return [years, months, days];
          }

          if (index === 0) break

          currentNum = (currentNum - nums[index - 1]).toString();
          index--;
        }
      }
    } else if (algorithm === "sum increment") {
      index = nums.length - 1;

      while (true) {
        currentNum = (currentNum + (index + 1)).toString();
        index++;

        if (currentNum < 10) {
          let [years, months, days, _] = getDate(currentNum);
          return [years, months, days];
        }

        if (currentNum >= 10000) {
          return false;
        }
      }
    } else if (algorithm === "subtract decrement") {
      if (nums.length > 1) {
        index = nums.length - 1;
        currentNum = (currentNum - (index + 1)).toString();
        index--;

        while (true) {
          if (currentNum < 0) {
            return "not possible, cannot go negative"
          }

          if (currentNum < 10) {
            let [years, months, days, _] = getDate(currentNum);
            return [years, months, days];
          }

          if (index === 0) break

          currentNum = (currentNum - (index)).toString();
          index--;
        }
      }
    }
  }

  function sortNums() {
    nums.sort((a, b) => a - b);
    setSeq(nums.join(', '));
  }

  function getDate(num) {
    const rem1 = num % 10;
    const rem2 = num % 100 / 10;
    const rem3 = num % 1000 / 100;
    const rem4 = num / 1000;

    return [rem4, rem3, rem2, rem1];
  }

  return (
    <div className="App">
        <h1 className='title'>White Hat Sequences</h1>

        <div className='equation-board'>
          <span>{seq}</span>
          <button onClick={sortNums}>Sort!</button>
          <span>Algorithm(s):</span>
          <span><button onClick={e => console.log(incident('sum sequential'))}>Sum sequential</button></span>
          <span><button onClick={e => console.log(incident('subtract sequential'))}>Subtract sequential</button></span>
          <span><button onClick={e => console.log(incident('sum increment'))}>Sum increment</button></span>
          <span><button onClick={e => console.log(incident('subtract decrement'))}>Subtract decrement</button></span>
        </div>
    </div>
  );
}

